#!/bin/bash
# Generated by Claude Fable 5 (Anthropic)
# FISH — rebuild the packages that INSTANTIATE header-level FISH tracepoints.
#
# Why: some FISH tracepoints live in rclcpp *headers* (template constructors —
# GenericSubscription: rclcpp_subscription_init + callback_added +
# callback_register; publisher.hpp intra-process publish_link; …). A header
# patch only reaches code that is COMPILED against the overlay. Anything
# prebuilt against stock rclcpp (apt ROS packages, the Autoware install space
# of the official images) keeps the stock instantiation → the E is seen (rcl,
# shared lib) but the F never appears. A source-built stack that sources the
# overlay before `colcon build` does not have this problem; prebuilt installs
# must rebuild the users of those headers. This script does that INSIDE the
# container, into the same overlay workspace (so `source
# $OVERLAY_WS/install/setup.bash` — which every FISH shell already does —
# shadows the prebuilt copies), and records what it did.
#
# Discovery (default): every package under the provenance source roots whose
# sources call create_generic_subscription / GenericSubscription and which is
# installed (share/<pkg> exists in $INSTALL or $ROS). Override with PKGS="a b".
#
# usage (in container): scripts/rebuild_header_tracepoint_users.sh
#   env: OVERLAY_WS=/root/trace_overlay_ws  SRC_ROOTS="/opt/fish_provenance/src /opt/fish_provenance_ros/src"
#        INSTALL=/opt/autoware  ROS=/opt/ros/humble  PKGS=""  PATTERN='create_generic_subscription|GenericSubscription'
set -u
OVERLAY_WS=${OVERLAY_WS:-/root/trace_overlay_ws}
SRC_ROOTS=${SRC_ROOTS:-"/opt/fish_provenance/src /opt/fish_provenance_ros/src"}
INSTALL=${INSTALL:-/opt/autoware}
ROS=${ROS:-/opt/ros/humble}
PATTERN=${PATTERN:-'create_generic_subscription|GenericSubscription'}
PKGS=${PKGS:-}
log(){ echo "[rebuild] $*"; }

# 1. discover ------------------------------------------------------------------
declare -A SRC_OF
if [ -z "$PKGS" ]; then
  for root in $SRC_ROOTS; do
    [ -d "$root" ] || continue
    for f in $(grep -rlE "$PATTERN" --include=*.cpp --include=*.hpp --include=*.h "$root" 2>/dev/null | grep -v "/test/\|/rclcpp/"); do
      d=$(dirname "$f")
      while [ "$d" != "/" ] && [ ! -f "$d/package.xml" ]; do d=$(dirname "$d"); done
      [ -f "$d/package.xml" ] || continue
      p=$(grep -o "<name>[^<]*" "$d/package.xml" | head -1 | cut -d">" -f2)
      if [ -d "$INSTALL/share/$p" ] || [ -d "$ROS/share/$p" ]; then SRC_OF[$p]="$d"; fi
    done
  done
  PKGS="${!SRC_OF[@]}"
else
  for p in $PKGS; do
    d=$(grep -rl "<name>$p</name>" --include=package.xml $SRC_ROOTS 2>/dev/null | head -1)
    [ -n "$d" ] && SRC_OF[$p]=$(dirname "$d") || log "WARN: no source for $p"
  done
fi
[ -n "$PKGS" ] || { log "nothing to rebuild (no installed package matches '$PATTERN')"; exit 0; }
log "packages instantiating header-level tracepoints ($PATTERN): $PKGS"

# 2. stage sources into the overlay workspace -----------------------------------
mkdir -p "$OVERLAY_WS/src"
for p in $PKGS; do
  rm -rf "$OVERLAY_WS/src/$p"
  cp -r "${SRC_OF[$p]}" "$OVERLAY_WS/src/$p"
  log "  $p ← ${SRC_OF[$p]} (version $(grep -o '<version>[^<]*' "$OVERLAY_WS/src/$p/package.xml" | cut -d'>' -f2); installed $(grep -o '<version>[^<]*' "$INSTALL/share/$p/package.xml" "$ROS/share/$p/package.xml" 2>/dev/null | head -1 | cut -d'>' -f2))"
done

# 3. build against the overlay (sourced LAST so its rclcpp headers win) -----------
set +u
source "$ROS/setup.bash"
[ -f "$INSTALL/setup.bash" ] && source "$INSTALL/setup.bash"
source "$OVERLAY_WS/install/setup.bash"
set -u
cd "$OVERLAY_WS"
colcon build --packages-select $PKGS --cmake-args -DBUILD_TESTING=OFF -DCMAKE_BUILD_TYPE=Release 2>&1 | tail -8
rc=${PIPESTATUS[0]}

# 4. verify: CMake must have resolved rclcpp from the overlay and the compiler
#    include lines must point at the overlay headers (flags.make) --------------
ok=1
for p in $PKGS; do
  cache="$OVERLAY_WS/build/$p/CMakeCache.txt"
  if grep -q "^rclcpp_DIR:PATH=$OVERLAY_WS/install/rclcpp/" "$cache" 2>/dev/null \
     && grep -rqs -- "-isystem $OVERLAY_WS/install/rclcpp/include" "$OVERLAY_WS/build/$p/CMakeFiles"; then
    log "  $p: compiled against $OVERLAY_WS/install/rclcpp (rclcpp_DIR + -isystem) ✔"
  else
    log "  $p: WARNING — overlay rclcpp not used (check $cache rclcpp_DIR and CMakeFiles/*/flags.make)"; ok=0
  fi
  [ -d "$OVERLAY_WS/install/$p" ] && log "  $p: installed → $OVERLAY_WS/install/$p (shadows $( [ -d $INSTALL/share/$p ] && echo $INSTALL || echo $ROS )/share/$p)"
done
python3 - "$OVERLAY_WS" "$PATTERN" $PKGS <<'PY'
import sys, json, os, time
ws, pat, pkgs = sys.argv[1], sys.argv[2], sys.argv[3:]
m = os.path.join(ws, "fish_rebuilt_packages.json")
d = json.load(open(m)) if os.path.exists(m) else {"rebuilt": {}}
for p in pkgs:
    d["rebuilt"][p] = {"pattern": pat, "at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}
json.dump(d, open(m, "w"), indent=1)
print(f"[rebuild] manifest → {m}: {sorted(d['rebuilt'])}")
PY
log "done (colcon rc=$rc, verify=$ok)"
exit $(( rc != 0 || ok == 0 ))
